using System;
using UniRx;
using UnityEngine;

namespace Workspace.koto_thing
{
    public class DocumentScreenPresenter : MonoBehaviour, IDisposable
    {
        [SerializeField] private DocumentScreenModel model;
        [SerializeField] private DocumentScreenView view;

        private CompositeDisposable disposables = new ();

        private void Start()
        {
            SubscribeEvents();
        }

        private void Update()
        {

        }

        private void SubscribeEvents()
        {
            model.OnChanged
                .Subscribe(model =>
                {
                    view.Apply(model);
                })
                .AddTo(disposables);
        }

        public void Open(DocumentData data)
        {
            if (model == null || view == null || data == null) return;
            model.Load(data);
            view.Show();
            view.Apply(model); // 初期ページ反映
        }

        public void Close() => view?.Hide();

        public void NextPage() => model?.NextPage();
        public void PrevPage() => model?.PrevPage();
        public void SetPage(int index) => model?.SetPage(index);

        private void OnDestroy()
        {
            Dispose();
        }

        public void Dispose()
        {
            disposables.Dispose();
        }
    }
}

